-- Project data only. Never run this schema against n8n's internal DB.
CREATE TABLE schema_migrations(version TEXT PRIMARY KEY NOT NULL, applied_at TEXT NOT NULL, checksum TEXT NOT NULL);
CREATE TABLE migration_runs(id TEXT PRIMARY KEY NOT NULL, input_snapshot TEXT NOT NULL, importer_version TEXT NOT NULL, started_at TEXT NOT NULL, completed_at TEXT, status TEXT NOT NULL CHECK(status IN ('running','complete','failed','held')), result_json TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(result_json)));
CREATE TABLE sync_runs(id TEXT PRIMARY KEY NOT NULL, request_hash TEXT NOT NULL, operation TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('running','complete','failed')), started_at TEXT NOT NULL, completed_at TEXT, result_json TEXT CHECK(result_json IS NULL OR json_valid(result_json)));
CREATE TABLE cutover_state(feature TEXT PRIMARY KEY NOT NULL CHECK(feature IN ('comparison','dashboard','weekly','ai-reader','n8n-daily')), read_source TEXT NOT NULL DEFAULT 'legacy' CHECK(read_source IN ('legacy','project-db')), write_target TEXT NOT NULL DEFAULT 'legacy' CHECK(write_target IN ('legacy','project-db')), changed_at TEXT NOT NULL, rollback_state TEXT NOT NULL DEFAULT 'not-started' CHECK(rollback_state IN ('not-started','verified','rolled-back')));
CREATE TABLE articles(id TEXT PRIMARY KEY NOT NULL, title TEXT NOT NULL, url TEXT NOT NULL, excerpt TEXT NOT NULL DEFAULT '', source TEXT NOT NULL DEFAULT '', published_at TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE article_identifiers(id TEXT PRIMARY KEY NOT NULL, article_id TEXT NOT NULL REFERENCES articles(id), source TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('legacy_key','original_url','resolved_url','source_record')), value TEXT NOT NULL CHECK(length(value)>0), match_state TEXT NOT NULL CHECK(match_state IN ('exact','confirmed','held')), UNIQUE(article_id,source,kind,value));
CREATE UNIQUE INDEX unique_legacy_key ON article_identifiers(source,kind,value) WHERE kind='legacy_key';
CREATE TABLE collection_runs(id TEXT PRIMARY KEY NOT NULL, source TEXT NOT NULL, source_record TEXT NOT NULL, run_date TEXT NOT NULL, workflow_execution_id TEXT, search_conditions_json TEXT NOT NULL CHECK(json_valid(search_conditions_json)), observed_at TEXT NOT NULL, UNIQUE(source,source_record));
CREATE TABLE article_occurrences(id TEXT PRIMARY KEY NOT NULL, collection_run_id TEXT NOT NULL REFERENCES collection_runs(id), article_id TEXT NOT NULL REFERENCES articles(id), source_record TEXT NOT NULL, title TEXT NOT NULL, excerpt TEXT NOT NULL, url TEXT NOT NULL, published_at TEXT, observations_json TEXT NOT NULL CHECK(json_valid(observations_json)), UNIQUE(collection_run_id,source_record));
CREATE TABLE content_payloads(id TEXT PRIMARY KEY NOT NULL, payload_hash TEXT NOT NULL UNIQUE CHECK(length(payload_hash)=64), text TEXT NOT NULL, text_hash TEXT NOT NULL CHECK(length(text_hash)=64), markdown TEXT NOT NULL, metadata_json TEXT NOT NULL CHECK(json_valid(metadata_json)), non_content_text TEXT NOT NULL DEFAULT '', extraction_scope TEXT NOT NULL DEFAULT '', raw_json TEXT NOT NULL CHECK(json_valid(raw_json)));
CREATE TABLE article_content_versions(id TEXT PRIMARY KEY NOT NULL, article_id TEXT NOT NULL REFERENCES articles(id), payload_id TEXT NOT NULL REFERENCES content_payloads(id), first_observed_at TEXT NOT NULL, last_observed_at TEXT NOT NULL, UNIQUE(article_id,payload_id));
CREATE TABLE content_fetch_attempts(id TEXT PRIMARY KEY NOT NULL, article_id TEXT NOT NULL REFERENCES articles(id), version_id TEXT REFERENCES article_content_versions(id), fetched_at TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('verified','partial','unavailable','unverified','metadata_only','pending','failed')), completeness TEXT, original_url TEXT NOT NULL, resolved_url TEXT, failure_reason TEXT, extraction_method TEXT, retry_after TEXT, raw_json TEXT NOT NULL CHECK(json_valid(raw_json)));
CREATE TABLE review_records(id TEXT PRIMARY KEY NOT NULL, article_id TEXT NOT NULL REFERENCES articles(id), content_version_id TEXT REFERENCES article_content_versions(id), input_hash TEXT NOT NULL, rule_hash TEXT NOT NULL, basis TEXT NOT NULL, reviewer TEXT NOT NULL, reviewed_at TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('current','held','needs_review','superseded')), raw_json TEXT NOT NULL CHECK(json_valid(raw_json)));
CREATE TABLE review_task_statuses(review_id TEXT NOT NULL REFERENCES review_records(id), task TEXT NOT NULL CHECK(task IN ('article-summary','talent-index','article-classification')), status TEXT NOT NULL CHECK(status IN ('ready','held','needs_review')), PRIMARY KEY(review_id,task));
CREATE TABLE review_evidence(id TEXT PRIMARY KEY NOT NULL, review_id TEXT NOT NULL REFERENCES review_records(id), input_field TEXT NOT NULL, start_offset INTEGER NOT NULL CHECK(start_offset>=0), end_offset INTEGER NOT NULL CHECK(end_offset>start_offset), quote TEXT NOT NULL CHECK(length(quote)>0));
CREATE TABLE review_facts(id TEXT PRIMARY KEY NOT NULL, review_id TEXT NOT NULL REFERENCES review_records(id), fact TEXT NOT NULL, raw_json TEXT NOT NULL CHECK(json_valid(raw_json)));
CREATE TABLE review_fact_evidence(fact_id TEXT NOT NULL REFERENCES review_facts(id), evidence_id TEXT NOT NULL REFERENCES review_evidence(id), PRIMARY KEY(fact_id,evidence_id));
CREATE TABLE review_entities(id TEXT PRIMARY KEY NOT NULL, review_id TEXT NOT NULL REFERENCES review_records(id), name TEXT NOT NULL, kind TEXT NOT NULL, raw_json TEXT NOT NULL CHECK(json_valid(raw_json)));
CREATE TABLE review_entity_evidence(entity_id TEXT NOT NULL REFERENCES review_entities(id), evidence_id TEXT NOT NULL REFERENCES review_evidence(id), PRIMARY KEY(entity_id,evidence_id));
CREATE TABLE article_summaries(id TEXT PRIMARY KEY NOT NULL, article_id TEXT NOT NULL REFERENCES articles(id), review_id TEXT REFERENCES review_records(id), summary TEXT NOT NULL, saved_at TEXT NOT NULL, version INTEGER NOT NULL CHECK(version>0), is_current INTEGER NOT NULL CHECK(is_current IN (0,1)), source TEXT NOT NULL, raw_json TEXT NOT NULL CHECK(json_valid(raw_json)), UNIQUE(article_id,version));
CREATE UNIQUE INDEX current_summary ON article_summaries(article_id) WHERE is_current=1;
CREATE TABLE talents(id TEXT PRIMARY KEY NOT NULL, display_name TEXT NOT NULL, organization TEXT NOT NULL DEFAULT '', status TEXT NOT NULL CHECK(status IN ('pending','approved','rejected')), search_enabled INTEGER NOT NULL CHECK(search_enabled IN (0,1)), auto_discovered INTEGER NOT NULL CHECK(auto_discovered IN (0,1)), last_seen_at TEXT, raw_json TEXT NOT NULL CHECK(json_valid(raw_json)));
CREATE TABLE talent_aliases(talent_id TEXT NOT NULL REFERENCES talents(id), alias TEXT NOT NULL, PRIMARY KEY(talent_id,alias));
CREATE TABLE article_talents(id TEXT PRIMARY KEY NOT NULL, article_id TEXT NOT NULL REFERENCES articles(id), talent_id TEXT NOT NULL REFERENCES talents(id), review_id TEXT REFERENCES review_records(id), evidence TEXT NOT NULL, confidence REAL NOT NULL CHECK(confidence>=0 AND confidence<=1), state TEXT NOT NULL CHECK(state IN ('current','held','superseded','proposed')), raw_json TEXT NOT NULL CHECK(json_valid(raw_json)));
CREATE UNIQUE INDEX current_article_talent ON article_talents(article_id,talent_id) WHERE state='current';
CREATE TABLE article_classifications(id TEXT PRIMARY KEY NOT NULL, article_id TEXT NOT NULL REFERENCES articles(id), review_id TEXT REFERENCES review_records(id), article_type TEXT NOT NULL, primary_category TEXT NOT NULL, relevance TEXT NOT NULL CHECK(relevance IN ('in_scope','low_relevance','out_of_scope')), confidence REAL NOT NULL CHECK(confidence>=0 AND confidence<=1), evidence TEXT NOT NULL, classified_at TEXT NOT NULL, version INTEGER NOT NULL CHECK(version>0), is_current INTEGER NOT NULL CHECK(is_current IN (0,1)), raw_json TEXT NOT NULL CHECK(json_valid(raw_json)), UNIQUE(article_id,version));
CREATE UNIQUE INDEX current_classification ON article_classifications(article_id) WHERE is_current=1;
CREATE TABLE classification_secondary_categories(classification_id TEXT NOT NULL REFERENCES article_classifications(id), category TEXT NOT NULL, PRIMARY KEY(classification_id,category));
CREATE TABLE article_feedback(id TEXT PRIMARY KEY NOT NULL, article_id TEXT NOT NULL REFERENCES articles(id), is_rejected INTEGER NOT NULL CHECK(is_rejected IN (0,1)), reason_code TEXT NOT NULL, reviewed_at TEXT NOT NULL, source TEXT NOT NULL, version INTEGER NOT NULL CHECK(version>0), is_current INTEGER NOT NULL CHECK(is_current IN (0,1)), raw_json TEXT NOT NULL CHECK(json_valid(raw_json)), UNIQUE(article_id,version));
CREATE UNIQUE INDEX current_feedback ON article_feedback(article_id) WHERE is_current=1;
CREATE TABLE consolidation_conflicts(id TEXT PRIMARY KEY NOT NULL, kind TEXT NOT NULL, article_id TEXT REFERENCES articles(id), reason TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('unresolved','approved','rejected')), details_json TEXT NOT NULL CHECK(json_valid(details_json)), created_at TEXT NOT NULL);
CREATE TABLE source_records(id TEXT PRIMARY KEY NOT NULL, migration_run_id TEXT REFERENCES migration_runs(id), source_path TEXT NOT NULL, record_position TEXT NOT NULL, input_hash TEXT NOT NULL, importer_version TEXT NOT NULL, target_kind TEXT, target_id TEXT, state TEXT NOT NULL CHECK(state IN ('imported','held')), reason TEXT, raw_json TEXT NOT NULL CHECK(json_valid(raw_json)), UNIQUE(source_path,record_position,input_hash));
CREATE TRIGGER immutable_migration_runs_id BEFORE UPDATE OF id ON migration_runs WHEN NEW.id!=OLD.id BEGIN SELECT RAISE(ABORT,'immutable id'); END;
